ds_sponsored_product_ads UNION ALL SELECT DISTINCT adid ,UPPER(asin) AS asin ,adgroupid ,campaignid ,\'PRODUCT\' AS landingpage FROM appldatabase.maplemonk.Amazon_Advertisement_Alphanso_amazonads_sponsored_display_product_ads ; CREATE OR REPLACE TABLE appldatabase.maplemonk.Alphanso_amazon_ads_targeting_details AS SELECT targetid, adgroupid, campaignid, LISTAGG(targeting_type, \',\') WITHIN GROUP (ORDER BY targeting_type ASC) AS targeting_type, LISTAGG(targeting_value, \',\') WITHIN GROUP (ORDER BY targeting_type ASC) AS targeting_value FROM ( SELECT targetid, adgroupid, campaignid, CAST(PARSE_JSON(t.value):type AS STRING) AS targeting_type, CAST(PARSE_JSON(t.value):value AS STRING) AS targeting_value FROM appldatabase.maplemonk.Amazon_Advertisement_Alphanso_amazonads_sponsored_display_targetings, LATERAL FLATTEN(input => PARSE_JSON(expression)) AS t ) GROUP BY 1,2,3 UNION ALL SELECT targetid, adgroupid, campaignid, LISTAGG(targeting_type, \',\') WITHIN GROUP (ORDER BY targeting_type ASC) AS targeting_type, LISTAGG(targeting_value, \',\') WITHIN GROUP (ORDER BY targeting_type ASC) AS targeting_value FROM ( SELECT targetid, adgroupid, campaignid, CAST(PARSE_JSON(t.value):type AS STRING) AS targeting_type, CAST(PARSE_JSON(t.value):value AS STRING) AS targeting_value FROM appldatabase.maplemonk.Amazon_Advertisement_Alphanso_amazonads_sponsored_product_targetings_v3_mm, LATERAL FLATTEN(input => PARSE_JSON(expression)) AS t ) GROUP BY 1,2,3 ; CREATE OR REPLACE TABLE appldatabase.maplemonk.Alphanso_amazon_ads_keyword_details AS SELECT DISTINCT keywordid ,UPPER(keywordtext) AS keywordtext ,adgroupid ,campaignid ,UPPER(matchtype) AS matchtype FROM appldatabase.maplemonk.Amazon_Advertisement_Alphanso_amazonads_sponsored_brands_keywords UNION ALL SELECT DISTINCT keywordid ,UPPER(keywordtext) AS keywordtext ,adgroupid ,campaignid ,CAST(NULL AS STRING) AS matchtype FROM appldatabase.maplemonk.Amazon_Advertisement_Alphanso_amazonads_sponsored_product_keywords ; CREATE OR REPLACE TABLE appldatabase.maplemonk.Alphanso_amazon_ads_profile_details AS SELECT profileid ,CAST(PARSE_JSON(accountinfo):name AS STRING) AS ProfileName ,CAST(PARSE_JSON(accountinfo):id AS STRING) AS SELLERID ,UPPER(CAST(PARSE_JSON(accountinfo):type AS STRING)) AS ACCOUNTYPE ,countryCode ,TIMEZONE FROM appldatabase.maplemonk.Amazon_Advertisement_Alphanso_amazonads_profiles ;",
